import React from 'react';

import clsx from 'clsx';

import styles from './styles.module.less';

const HorizontalScrollable: React.FC<React.HTMLAttributes<HTMLDivElement>> = ({
  className,
  children,
  ...rest
}) => {
  const elRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!elRef.current) return;
    const el = elRef.current as HTMLDivElement;
    const gap = 20;
    const handleScroll = () => {
      const contentScrollWidth = el.scrollWidth - el.offsetWidth;

      const needBefore = el.scrollLeft > gap;
      const needAfter = contentScrollWidth - el.scrollLeft > gap;
      const needBoth = needBefore && needAfter;

      el.classList.remove(styles.before);
      el.classList.remove(styles.after);
      el.classList.remove(styles.both);

      if (needBoth) {
        el.classList.add(styles.both);
      } else if (needBefore) {
        el.classList.add(styles.before);
      } else if (needAfter) {
        el.classList.add(styles.after);
      }
    };
    elRef.current.addEventListener('scroll', handleScroll);

    handleScroll();

    return () => elRef.current?.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div {...rest} ref={elRef} className={clsx(styles.horizontalScrollable, className)}>
      {children}
    </div>
  );
};

export default HorizontalScrollable;
