import React from 'react';

import clsx from 'clsx';
import * as SunCalc from 'suncalc';

import styles from './styles.module.less';

interface IScheduleDaySunProps extends React.HTMLAttributes<HTMLDivElement> {
  date: Date;
  coords: [number, number, number?];
}

const ScheduleDaySun: React.FC<IScheduleDaySunProps> = ({ date, coords, className, ...rest }) => {
  const suncalc = SunCalc.getTimes(new Date(date.setHours(12)), ...coords);
  const data: Record<
    keyof SunCalc.GetTimesResult,
    { color: string; name: string; isPeak?: boolean }
  > = {
    nadir: {
      color: `#232323`,
      name: `Надир (самый темный момент ночи, солнце находится в самой низкой точке)`,
      isPeak: true,
    },
    nightEnd: {
      color: `#ff0000`,
      name: `Окончание ночи (начинаются утренние астрономические сумерки)`,
    },
    nauticalDawn: {
      color: `#ff4d00`,
      name: `Начинается навигационный рассвет (начинаются утренние навигационные сумерки)`,
    },
    dawn: {
      color: `#ff6700`,
      name: `Рассвет (заканчиваются утренние навигационные сумерки, начинаются утренние гражданские сумерки)`,
    },
    sunrise: {
      color: `#ff8100`,
      name: `Восход солнца (верхний край солнца появляется на горизонте)`,
    },
    sunriseEnd: {
      color: `#ffa700`,
      name: `Окончание восхода солнца (нижний край солнца касается горизонта)`,
    },
    goldenHourEnd: {
      color: `#ffffff`,
      name: `Окончание утреннего золотого часа (мягкий свет, лучшее время для фотосъемки)`,
    },
    solarNoon: {
      color: `#ffdd40`,
      name: `Солнечный полдень (солнце находится в самой высокой точке)`,
      isPeak: true,
    },
    goldenHour: {
      color: `#ffffff`,
      name: `Начало вечернего золотого часа. Хорошее время для фотосъемки`,
    },
    sunsetStart: {
      color: `#eeaf61`,
      name: `Начало заката (нижний край солнца касается горизонта)`,
    },
    sunset: {
      color: `#fb9062`,
      name: `Закат (солнце скрывается за горизонтом, начинаются вечерние гражданские сумерки)`,
    },
    dusk: {
      color: `#ee5d6c`,
      name: `Сумерки (начинаются вечерние навигационные сумерки)`,
    },
    nauticalDusk: {
      color: `#ce4993`,
      name: `Начинаются навигационные сумерки (начинаются вечерние астрономические сумерки)`,
    },
    night: {
      color: `#6a0d83`,
      name: `Начинается ночь (достаточно темно для астрономических наблюдений)`,
    },
  };

  const startOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 0, 0, 0, 0);
  const endOfDay = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59, 999);

  return (
    <>
      {suncalc.nightEnd.getTime() > startOfDay.getTime() && (
        <div
          {...rest}
          style={
            {
              top: 0,
              height: suncalc.nightEnd.getHours() * 60 + suncalc.nightEnd.getMinutes(),
              '--bg1': data.night.color,
              '--bg2': data.nadir.color,
            } as React.CSSProperties
          }
          className={clsx(styles.sun, styles.night, className)}
        />
      )}
      {Object.entries(data)
        .filter(([, v]) => !v.isPeak)
        .map(([k], i, all) => {
          const key = k as keyof SunCalc.GetTimesResult;
          const cur = suncalc[key] < startOfDay ? startOfDay : suncalc[key];

          const nextKey =
            i < all.length - 1 ? (all[i + 1][0] as keyof SunCalc.GetTimesResult) : undefined;

          let nextV = nextKey ? suncalc[nextKey] : undefined;

          if (!nextV || nextV > endOfDay) nextV = endOfDay;

          const top = cur.getHours() * 60 + cur.getMinutes();
          const height = (nextV.getTime() - cur.getTime()) / 60000;

          return (
            <div
              {...rest}
              key={k}
              title={[
                key,
                data[key].name,
                [key, suncalc[key].toLocaleString(), cur.toLocaleString()].join(' - '),
                [nextKey, '', nextV.toLocaleString()].join(' - '),
              ].join('\n')}
              style={
                {
                  top,
                  height,
                  '--bg1': i == 0 ? 'rgba(0,0,0,0.5)' : data[key].color,
                  '--bg2': nextKey ? data[nextKey].color : 'rgba(0,0,0,0.5)',
                } as React.CSSProperties
              }
              className={clsx(styles.sun, styles[k], className)}
            />
          );
        })}
    </>
  );
};

export default ScheduleDaySun;
