import { get, handleApiError, post } from '@helpers/httpClient';

export interface IHikingKeyPointDTO {
  id: string;
  name: string;
  date: string;
  lat: string;
  lon: string;
}

export const getHikingKeyPoints = async (id_hiking: number) => {
  return get('/ajax/hiking/keypoints.php', { id_hiking }).then<IHikingKeyPointDTO[]>(
    handleApiError,
  );
};

export const addHikingKeyPoint = async (
  id_hiking: number,
  keyPoint: IHikingKeyPointDTO,
): Promise<IHikingKeyPointDTO> => {
  const data = { ...keyPoint, id_hiking };
  const res = await post('/ajax/hiking/keypoint_add.php', data).then<{
    success: boolean;
    id: string;
  }>(handleApiError);
  return { ...keyPoint, id: res.id };
};

export const updateHikingKeyPoint = async (
  id_hiking: number,
  keyPoint: IHikingKeyPointDTO,
): Promise<IHikingKeyPointDTO> => {
  const data = { ...keyPoint, id_hiking };
  await post('/ajax/hiking/keypoint_add.php', data).then<{
    success: boolean;
  }>(handleApiError);
  return { ...keyPoint };
};

export const deleteHikingKeyPoint = async (
  id_hiking: number,
  id_keyPoint: string,
): Promise<boolean> => {
  const res = await post('/ajax/hiking/keypoint_del.php', { id_hiking, id: id_keyPoint }).then<{
    success: boolean;
  }>(handleApiError);
  return !!res.success;
};
