import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import HikingBaseInfoForm from '@apps/Hiking/forms/HikingBaseInfoForm';

const HikingEditBase: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  if (!hikingContext) return <div>Wrong hiking context</div>;
  return (
    <section className="p-3">
      <HikingBaseInfoForm hikingData={hikingContext} />
    </section>
  );
};

export default HikingEditBase;
