import React, { FormEvent } from 'react';

import { getInputDate } from '@helpers/dateHelper';
import PohButton from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import { showModal } from '@ui-kit/Modal';

interface IScheduleSwitchDatesProps {
  d1?: Date;
  d2?: Date;
  onChange: (d1: Date, d2: Date) => void;
}

const ScheduleSwitchDates: React.FC<IScheduleSwitchDatesProps> = ({
  d1: defaultD1,
  d2: defaultD2,
  onChange,
}) => {
  const [d1, setD1] = React.useState(defaultD1 ? getInputDate(defaultD1, true) : '');
  const [d2, setD2] = React.useState(defaultD2 ? getInputDate(defaultD2, true) : '');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    onChange(new Date(d1), new Date(d2));
  };

  return (
    <form onSubmit={handleSubmit}>
      <PohInput type={InputTypes.date} value={d1} onChange={setD1} label="Дата-1" />
      <PohInput type={InputTypes.date} value={d2} onChange={setD2} label="Дата-2" />
      <PohButton type="submit">Сохранить</PohButton>
    </form>
  );
};

export const selectTwoDatesAsync = (
  props: Omit<IScheduleSwitchDatesProps, 'onChange'>,
): Promise<{ d1: Date; d2: Date }> => {
  return new Promise((res) => {
    showModal({
      title: 'Выбор дат',
      children: (clos) => (
        <ScheduleSwitchDates
          {...props}
          onChange={(d1, d2) => {
            res({ d1, d2 });
            clos();
          }}
        />
      ),
    });
  });
};
