import { useState, useEffect } from 'react';

import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import {
  approveVacancy,
  getHikingVacancyResponses,
} from '../../../@services/hikingPositionsAndVacancies.service';
import { IHikingData } from '../../../@types/hiking.types';
import {
  IHikingVacancy,
  IHikingVacancyResponse,
} from '../../../@types/hikingPositionsAndVacancies.types';

interface IViewModalProps {
  vacancy: IHikingVacancy;
  hikingData: IHikingData;
}

function ViewModal({ onSave, vacancy, hikingData }: IViewModalProps & { onSave: () => void }) {
  const [data, setData] = useState<IHikingVacancyResponse[]>([]);
  useEffect(() => {
    const fetch = async () => {
      getHikingVacancyResponses(vacancy.id, hikingData.id).then(setData);
    };
    fetch();
  }, []);

  return (
    <div>
      <PohList
        data={data.map((x) => ({
          key: x.id,
          content: (
            <>
              {x.user.name} {x.user.surname}
              {'   '}
              <PohButton
                onClick={async () => {
                  approveVacancy(hikingData.id, x.id).then(() => {
                    onSave();
                    notificationHelper.success('Done');
                  });
                }}
              >
                Утвердить
              </PohButton>
            </>
          ),
        }))}
      />
    </div>
  );
}

export const viewVacancyAsync = (
  vacancy: IHikingVacancy,
  hikingData: IHikingData,
): Promise<void> => {
  return new Promise((res) => {
    showModal({
      children: (clos: any) => (
        <ViewModal
          vacancy={vacancy}
          hikingData={hikingData}
          onSave={() => {
            res();
            clos();
          }}
        />
      ),
    });
  });
};

export default ViewModal;
