import React from 'react';

import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { confirmModal } from '@ui-kit/Modal';

import { IHikingVacancy } from '../../../@types/hikingPositionsAndVacancies.types';

interface IHikingEditVacanciesRowProps {
  vacancy: IHikingVacancy;
  onDelete: (vacancy: IHikingVacancy) => void;
  onEdit: (vacancy: IHikingVacancy) => void;
  onView: (vacancy: IHikingVacancy) => void;
}

function HikingEditVacanciesRow({
  vacancy,
  onDelete,
  onEdit,
  onView,
}: IHikingEditVacanciesRowProps) {
  return (
    <PohRow>
      <PohCol sm={3}>
        <strong>{vacancy.position.name}</strong>&nbsp;
        <PohBadge variant={BadgeVariant.Info} rounded onClick={() => onView(vacancy)}>
          {vacancy.responsesCount}
        </PohBadge>
      </PohCol>
      <PohCol sm={2}>до {vacancy.deadline.toLocaleDateString()}</PohCol>
      <PohCol sm={1}>
        <PohBadge variant={vacancy.isActive ? BadgeVariant.Success : BadgeVariant.Warning}>
          {vacancy.isActive ? 'актуально' : 'не актуально'}
        </PohBadge>
      </PohCol>
      <PohCol sm={4}>
        <em>{vacancy.comment}</em>
      </PohCol>
      <PohCol sm={2} className="text-end">
        <PohButton
          variant={ButtonVariant.Light}
          size={ButtonSize.Small}
          onClick={async () => {
            const ok = await confirmModal({
              children: `Точно удалить ваканcию ${vacancy.position.name}?`,
              confirmText: 'Удалить',
            });
            ok && onDelete(vacancy);
          }}
        >
          <PohIcon name={IconsEnum.trash} />
        </PohButton>{' '}
        <PohButton
          variant={ButtonVariant.Light}
          size={ButtonSize.Small}
          onClick={() => onEdit(vacancy)}
        >
          <PohIcon name={IconsEnum.edit} />
        </PohButton>
      </PohCol>
    </PohRow>
  );
}

export default HikingEditVacanciesRow;
